def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    tokens: list of strings, each either an integer literal or one of '+', '-', '*', '/'.
    Returns the integer result, with division truncating toward zero.
    """
    stack = []
    for tok in tokens:
        if tok not in {"+", "-", "*", "/"}:
            stack.append(int(tok))
        else:
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                stack.append(a + b)
            elif tok == '-':
                stack.append(a - b)
            elif tok == '*':
                stack.append(a * b)
            else:  # division truncates toward zero
                # Python's int() on a / b truncates toward zero for both signs.
                stack.append(int(a / b))
    return stack[0] if stack else 0

